/**
 *
 * ContextMenuGroup wraps a logical group of context menu items. Renders with role="group" and exposes its id so a nested ContextMenu.Label can be linked via aria-labelledby.
 *
 * [Live Demo](https://www.primereact.org/contextmenu/)
 *
 * @module ContextMenuGroup
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { ContextMenuRootInstance } from './ContextMenuRoot.types';
/**
 * Defines passthrough(pt) options type in ContextMenuGroup component.
 */
export type ContextMenuGroupPassThroughType<E> = PassThroughType<ContextMenuGroupInstance, E>;
/**
 * Defines passthrough(pt) options of ContextMenuGroup component.
 */
export interface ContextMenuGroupPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: ContextMenuGroupPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Context value shared between ContextMenuGroup and a nested ContextMenuLabel so the label id can be attached to the group's `aria-labelledby`.
 */
export interface ContextMenuGroupContextInterface {
    /**
     * The id of the group element.
     */
    groupId: string | undefined;
    /**
     * The id of the nested label element, when present.
     */
    labelId: string | undefined;
    /**
     * Setter used by a nested ContextMenu.Label to register its id with the group.
     */
    setLabelId: (id: string | undefined) => void;
}
/**
 * Defines valid properties in ContextMenuGroup component.
 */
export interface ContextMenuGroupProps extends BaseComponentProps<ContextMenuGroupInstance, unknown, ContextMenuGroupPassThrough> {
}
/**
 * Defines valid state in ContextMenuGroup component.
 */
export interface ContextMenuGroupState {
}
/**
 * Defines the methods and properties exposed by ContextMenuGroup component.
 */
export interface ContextMenuGroupExposes {
    /**
     * Instance of the ContextMenu component.
     */
    contextmenu: ContextMenuRootInstance | undefined | null;
    /**
     * Context exposed to nested ContextMenu.Label children.
     */
    context: ContextMenuGroupContextInterface;
}
/**
 * Instance of ContextMenuGroup component.
 */
export type ContextMenuGroupInstance = ComponentInstance<ContextMenuGroupProps, ContextMenuGroupState, ContextMenuGroupExposes>;
